import { test, expect } from '@playwright/test';

test('dashboard shows the latest invoice for the logged-in user', async ({ page }) => {
  await page.goto('/dashboard');
  // Wait for the real signal: the most recent invoice card.
  const invoiceCard = page.getByRole('region', { name: 'Latest invoice' });
  await expect(invoiceCard).toBeVisible();
  await expect(invoiceCard.getByText(/INV-\d{6}/)).toBeVisible();
  await expect(invoiceCard.getByRole('button', { name: 'Download PDF' })).toBeEnabled();
});
